else if (q.name) out = handleTool({ name: q.name, args: { merchant_id: q.merchant_id, last4: q.last4, date: q.date, time: q.time, issue: q.issue, reason: q.reason, outcome: q.outcome, summary: q.summary }, call: { call_id: q.call_id, transcript: q.transcript } });
else if (q.fn === 'sim') out = handleSim(q);
